do $$ begin
 if exists(select 1 from public.catalogue_sources t join jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2026-topps-stadium-club-wwe-checklist","set_id":"2026-topps-stadium-club-wwe","source":"Topps","purpose":"Checklist","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/2026_Topps_Stadium_Club_WWE_-_Checklist.pdf?v=1791221305","notes":"938 source rows; 930 physical card identities; 25 subsets. Chrome autograph II missing from checklist."},{"id":"2026-topps-stadium-club-wwe-odds","set_id":"2026-topps-stadium-club-wwe","source":"Topps","purpose":"Parallel applicability","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/2026_Topps_Stadium_Club_WWE_Odds.pdf?v=1791212522","notes":"122 odds rows retained in source; 117 mapped rules. Five Chrome II rows deferred. Pack odds do not establish serial caps."},{"id":"2026-topps-stadium-club-wwe-guide","set_id":"2026-topps-stadium-club-wwe","source":"Topps","purpose":"Release and explicit numbered editions","url":"https://ripped.topps.com/2026-topps-stadium-club-wwe-cards-collector-guide/","notes":"Four card-specific numbered editions confirmed. Guide Chrome autograph Pearl White/Gold Minted language conflicts with odds; not generated."}]'::jsonb) e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.source is distinct from e.source or t.purpose is distinct from e.purpose or t.url is distinct from e.url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_sources row; refusing overwrite'; end if;
end $$;
insert into public.catalogue_sources(id,set_id,source,purpose,url,notes) select id,set_id,source,purpose,url,notes from jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2026-topps-stadium-club-wwe-checklist","set_id":"2026-topps-stadium-club-wwe","source":"Topps","purpose":"Checklist","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/2026_Topps_Stadium_Club_WWE_-_Checklist.pdf?v=1791221305","notes":"938 source rows; 930 physical card identities; 25 subsets. Chrome autograph II missing from checklist."},{"id":"2026-topps-stadium-club-wwe-odds","set_id":"2026-topps-stadium-club-wwe","source":"Topps","purpose":"Parallel applicability","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/2026_Topps_Stadium_Club_WWE_Odds.pdf?v=1791212522","notes":"122 odds rows retained in source; 117 mapped rules. Five Chrome II rows deferred. Pack odds do not establish serial caps."},{"id":"2026-topps-stadium-club-wwe-guide","set_id":"2026-topps-stadium-club-wwe","source":"Topps","purpose":"Release and explicit numbered editions","url":"https://ripped.topps.com/2026-topps-stadium-club-wwe-cards-collector-guide/","notes":"Four card-specific numbered editions confirmed. Guide Chrome autograph Pearl White/Gold Minted language conflicts with odds; not generated."}]'::jsonb) on conflict do nothing;

do $$ begin
 if (select count(*) from public.catalogue_sets)<>24
 or (select count(*) from public.catalogue_cards)<>11298
 or (select count(*) from public.catalogue_variants)<>32568
 or (select count(*) from public.catalogue_cards where set_id='2026-topps-stadium-club-wwe')<>930
 or (select count(*) from public.catalogue_variants where set_id='2026-topps-stadium-club-wwe')<>934
 or (select count(*) from public.catalogue_subsets where set_id='2026-topps-stadium-club-wwe')<>25
 or exists(select 1 from public.catalogue_sets s where s.id in ('2026-topps-stadium-club-wwe','2026-topps-now-wwe') and (s.card_count<>(select count(*) from public.catalogue_cards c where c.set_id=s.id) or s.variant_count<>(select count(*) from public.catalogue_variants v where v.set_id=s.id)))
 or exists(select 1 from public.catalogue_subsets s where s.set_id in ('2026-topps-stadium-club-wwe','2026-topps-now-wwe') and s.card_count<>(select count(*) from public.catalogue_cards c where c.set_id=s.set_id and c.subset_code=s.subset_code))
 or exists(select 1 from public.catalogue_variants v left join public.catalogue_cards c on c.id=v.card_id where c.id is null or v.set_id<>c.set_id)
 then raise exception 'Catalogue count/linkage validation failed'; end if;
 if exists(select 1 from before_cards b left join public.catalogue_cards c on c.id=b.id where b.row is distinct from case when c.set_id='2026-topps-now-wwe' then to_jsonb(c)-'checklist_order' else to_jsonb(c) end)
 or exists(select 1 from before_variants b left join public.catalogue_variants c on c.id=b.id where b.row is distinct from case when c.set_id='2026-topps-now-wwe' then to_jsonb(c)-'variant_order' else to_jsonb(c) end)
 or exists(select 1 from before_sets b left join public.catalogue_sets c on c.id=b.id where b.row is distinct from case when c.id='2026-topps-now-wwe' then to_jsonb(c)-'card_count'-'variant_count'-'updated_at' else to_jsonb(c) end)
 or exists(select 1 from before_subsets b left join public.catalogue_subsets c on c.set_id=b.set_id and c.subset_code=b.subset_code where b.row is distinct from case when c.set_id='2026-topps-now-wwe' and c.subset_code='BASE' then to_jsonb(c)-'card_count' else to_jsonb(c) end)
 or exists(select 1 from before_rules b left join public.catalogue_parallel_rules c on c.id=b.id where b.row is distinct from to_jsonb(c))
 or exists(select 1 from before_sources b left join public.catalogue_sources c on c.id=b.id where b.row is distinct from to_jsonb(c))
 or exists((select row from before_collections except all select to_jsonb(c) from public.collection_items c) union all (select to_jsonb(c) from public.collection_items c except all select row from before_collections))
 or exists((select row from before_images except all select to_jsonb(c) from public.reference_images c) union all (select to_jsonb(c) from public.reference_images c except all select row from before_images))
 then raise exception 'Existing records changed; entire import rolled back'; end if;
end $$;
select 'catalogue_verified' as result,(select count(*) from public.catalogue_cards) as cards,(select count(*) from public.catalogue_variants) as variants,(select count(*) from public.collection_items) as collections;
commit;
